 name=v.get('name',v.get('view'));p=R/v['PNG']if v.get('PNG')else A/v.get('png',name+'.png');assert p.exists();expected=v.get('PNG_sha256',v.get('sha256'));assert not expected or sha(p)==expected
 shutil.copy2(p,O/(name+'.png'));exr=R/v['EXR']if v.get('EXR')else A/v.get('exr','raw/'+name+'.exr');assert exr.exists();shutil.copy2(exr,raw/(name+'.exr'));views.append(dict(name=name,PNG_sha256=sha(p),samples=v['samples'],actually_saved=True,source_author_view=v))
